<?php

declare(strict_types=1);

namespace Tests\Testo\Invoice\Peppol;

use App\Invoice\Peppol\PeppolPreSendValidation;
use Mockery as m;
use Testo\Assert;
use Testo\Test;
use Yiisoft\Translator\TranslatorInterface;

/**
 * The gate in front of a Peppol send. The valid document is a real invoice generated by PeppolHelper (from the
 * seeded happy-path fixture) and sanitised to virtual data, so "a valid invoice is not blocked" is tested against
 * the real generator's output and not a hand-built imitation.
 *
 * The gate is exactly as strong as PeppolValidator. It blocks arithmetic (BR-CO-*), code-list (BR-CL-*), tax
 * category (BR-S/E/Z-08) and Peppol-specific (PEPPOL-EN16931-R*) rule errors. It does not re-check the
 * mandatory-element presence rules (BR-01 to BR-09 and similar) on the finished XML: the UBL generator enforces
 * those while it builds the document and refuses incomplete data. These tests deliberately do not assert that
 * gap either way.
 */
#[Test]
final class PeppolPreSendValidationTest
{
    private function gate(): PeppolPreSendValidation
    {
        /** @var TranslatorInterface&m\MockInterface $translator */
        $translator = m::mock(TranslatorInterface::class);
        $translator->shouldReceive('translate')->andReturnUsing(static fn (string $id): string => $id);
        return new PeppolPreSendValidation($translator);
    }

    private function validInvoice(): string
    {
        return (string) file_get_contents(__DIR__ . '/Fixtures/valid-peppol-invoice.xml');
    }

    /** @return list<string> */
    private function rules(string $xml): array
    {
        return array_column($this->gate()->errors($xml), 'rule');
    }

    // ── errors() ─────────────────────────────────────────────────────────────

    public function aValidGeneratedInvoiceHasNoErrorsSoItIsNotBlocked(): void
    {
        Assert::same($this->gate()->errors($this->validInvoice()), []);
    }

    public function aTotalThatDoesNotAddUpIsReported(): void
    {
        $xml = (string) preg_replace('~(<cbc:PayableAmount[^>]*>)[^<]*~', '${1}999.99', $this->validInvoice(), 1);

        Assert::true(in_array('BR-CO-14', $this->rules($xml), true));
    }

    public function anInvoiceWithNoLinesIsReported(): void
    {
        $xml = (string) preg_replace('~<cac:InvoiceLine>.*</cac:InvoiceLine>~s', '', $this->validInvoice(), 1);

        Assert::true(in_array('BR-CO-10', $this->rules($xml), true));
    }

    public function aCurrencyThatDiffersFromTheInvoiceCurrencyIsReported(): void
    {
        $xml = (string) preg_replace(
            '~<cbc:DocumentCurrencyCode>[^<]*</cbc:DocumentCurrencyCode>~',
            '<cbc:DocumentCurrencyCode>EUR</cbc:DocumentCurrencyCode>',
            $this->validInvoice(),
            1,
        );

        Assert::true(in_array('PEPPOL-EN16931-R051', $this->rules($xml), true));
    }

    public function aDocumentThatIsNotAnInvoiceOrCreditNoteIsReported(): void
    {
        $errors = $this->gate()->errors('<?xml version="1.0"?><Order xmlns="urn:example:order"/>');

        Assert::same(count($errors), 1);
        Assert::true(str_contains($errors[0]['rule'] . $errors[0]['text'], 'peppol.unknown.document.type'));
    }

    public function textThatIsNotXmlIsReportedAsInvalidXml(): void
    {
        $errors = $this->gate()->errors('this is not xml');

        Assert::true($errors !== []);
        Assert::true(str_contains($errors[0]['rule'] . $errors[0]['text'], 'Invalid XML'));
    }

    public function everyErrorCarriesARuleAndATextAsStrings(): void
    {
        $xml = (string) preg_replace('~(<cbc:PayableAmount[^>]*>)[^<]*~', '${1}999.99', $this->validInvoice(), 1);

        foreach ($this->gate()->errors($xml) as $error) {
            Assert::same(array_keys($error), ['rule', 'text']);
            Assert::same($error['rule'], trim($error['rule'], ' :'));
        }
    }

    // ── isEnabled() ──────────────────────────────────────────────────────────

    public function theGateIsOnUnlessTheSettingIsExactlyZero(): void
    {
        Assert::true(PeppolPreSendValidation::isEnabled(null));
        Assert::true(PeppolPreSendValidation::isEnabled(''));
        Assert::true(PeppolPreSendValidation::isEnabled('1'));
        Assert::true(PeppolPreSendValidation::isEnabled('anything'));
        Assert::false(PeppolPreSendValidation::isEnabled('0'));
    }

    public function theSettingKeyIsTheOneTheSettingsTabSaves(): void
    {
        Assert::same(PeppolPreSendValidation::SETTING_KEY, 'peppol_validate_before_send');
    }

    // ── listHtml() ───────────────────────────────────────────────────────────

    public function theErrorListShowsEachRuleIdAndItsText(): void
    {
        $html = $this->gate()->listHtml([
            ['rule' => 'BR-CO-14', 'text' => 'Tax total mismatch'],
            ['rule' => '', 'text' => 'Invalid XML'],
        ]);

        Assert::same($html, '<ul><li><code>BR-CO-14</code> Tax total mismatch</li><li>Invalid XML</li></ul>');
    }

    public function theErrorListEncodesEverythingSoADocumentCannotInjectMarkup(): void
    {
        $html = $this->gate()->listHtml([['rule' => '<b>R</b>', 'text' => '<script>alert(1)</script>']]);

        Assert::false(str_contains($html, '<script>'));
        Assert::false(str_contains($html, '<b>'));
        Assert::true(str_contains($html, '&lt;script&gt;'));
    }

    public function onlyTheFirstTenErrorsAreListedAndTheRestAreCounted(): void
    {
        $errors = [];
        for ($i = 1; $i <= 13; $i++) {
            $errors[] = ['rule' => 'R' . $i, 'text' => 'text ' . $i];
        }

        $html = $this->gate()->listHtml($errors);

        Assert::same(substr_count($html, '<code>'), PeppolPreSendValidation::LISTED_ERRORS);
        Assert::true(str_contains($html, 'R10'));
        Assert::false(str_contains($html, 'R11'));
        Assert::true(str_contains($html, 'peppol.send.blocked.more'));
    }

    public function exactlyTenErrorsAddNoCountOfTheRest(): void
    {
        $errors = [];
        for ($i = 1; $i <= 10; $i++) {
            $errors[] = ['rule' => 'R' . $i, 'text' => 'text ' . $i];
        }

        Assert::false(str_contains($this->gate()->listHtml($errors), 'peppol.send.blocked.more'));
    }
}
